mapper.update:
update qms_change_revert set status = 'VOID', void_reason = #{reason}, voided_at = now(), voided_by = #{by},
                             row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where revert_id = #{id} and row_ver = #{rowVer} and status = 'ACTIVE'

update qms_change_effect set status = 'VOID', void_reason = #{reason}, voided_at = now(), voided_by = #{by},
                             row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where effect_id = #{id} and row_ver = #{rowVer} and status = 'ACTIVE'

mapper.select:
select m.value, m.ok_yn from qms_insp_meas m join qms_insp_line x on x.insp_line_id = m.insp_line_id and x.char_id = #{charId} join qms_insp h on h.insp_id = x.insp_id and h.status = 'JUDGED' where m.void_of_id is null and not exists (select 1 from qms_insp_meas v where v.void_of_id = m.meas_id)
and m.ok_yn is not null and m.value is not null
and h.item_id in #{x}
and m.occurred_at >= #{base} order by m.occurred_at, m.meas_id and m.occurred_at < #{base} order by m.occurred_at desc, m.meas_id desc
limit #{n}
